__import__('re')

def load_all_globs():
    t = open(RLM_SESSION_DIR + '/../../sessions/' + os.path.basename(RLM_SESSION_DIR) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_all_globs()

def get_full_lines(grid, value):
    rows = [r for r in range(len(grid)) if all(grid[r][c] == value for c in range(len(grid[0])))]
    cols = [c for c in range(len(grid[0])) if all(grid[r][c] == value for r in range(len(grid)))]
    return rows, cols

def transform(grid):
    values = set(val for row in grid for val in row)
    values = list(values)

    if len(values) == 0:
        return grid

    # Find foreground (value that forms full lines)
    foreground = None
    for v in values:
        fr, fc = get_full_lines(grid, v)
        if len(fr) > 0 or len(fc) > 0:
            foreground = v
            break

    if foreground is None:
        return grid

    fr, fc = get_full_lines(grid, foreground)
    num_full_lines = len(fr) + len(fc)

    # new_value = (num_full_lines + 1) // 2
    new_value = (num_full_lines + 1) // 2

    new_grid = [row[:] for row in grid]
    for r in fr:
        for c in range(len(grid[0])):
            if new_grid[r][c] == foreground:
                new_grid[r][c] = new_value
    for c in fc:
        for r in range(len(grid)):
            if new_grid[r][c] == foreground:
                new_grid[r][c] = new_value

    return new_grid

test_inp = G['Test input']
